388	// InitStats initalizes stats threads. We separate construction
389	// from initialization because the session provider needs the
390	// *StatsCoordinator handle (stats and provider are cyclically
391	// dependent), but several other initialization steps race on
392	// session variables if stats threads are started too early.
393	// xxx: separating provider/stats dependency is tough because
394	// the session is the runtime source of truth for both.
395	func (se *SqlEngine) InitStats(ctx context.Context) error {
396		// configuring stats depends on sessionBuilder
397		// sessionBuilder needs ref to statsProv
398		pro := se.GetUnderlyingEngine().Analyzer.Catalog.DbProvider.(dsess.DoltDatabaseProvider)
399		sqlCtx, err := se.NewLocalContext(ctx)
400		if err != nil {
401			return err
402		}
403		defer sql.SessionEnd(sqlCtx.Session)
404		sql.SessionCommandBegin(sqlCtx.Session)
405		defer sql.SessionCommandEnd(sqlCtx.Session)
406		dbs := pro.AllDatabases(sqlCtx)
407		statsPro := se.GetUnderlyingEngine().Analyzer.Catalog.StatsProvider
408		if sc, ok := statsPro.(*statspro.StatsController); ok {
409			_, memOnly, _ := sql.SystemVariables.GetGlobal(dsess.DoltStatsMemoryOnly)
410			sc.SetMemOnly(memOnly.(int8) == 1)
411	
412			if adder, ok := se.GetUnderlyingEngine().Analyzer.Catalog.DbProvider.(sqle.DatabaseHookRegistrar); ok {
413				adder.AddInitDatabaseHook(statspro.NewInitDatabaseHook(sc))
414				adder.AddDropDatabaseHook(statspro.NewDropDatabaseHook(sc))
415			}
416	
417			var sqlDbs []sql.Database
418			for _, db := range dbs {
419				sqlDbs = append(sqlDbs, db)
420			}
421	
422			err = sc.Init(sqlCtx, pro, se.NewDefaultContext, sqlDbs)
423			if err != nil {
424				return err
425			}
426	
427			if _, paused, _ := sql.SystemVariables.GetGlobal(dsess.DoltStatsPaused); paused.(int8) == 0 {
428				if err = sc.Restart(sqlCtx); err != nil {
429					return err
430				}
431			}
432		}
433		return nil
434	}
